#include "coagentics/analysis/Benchmark.hpp"
#include <cmath>
#include <memory>
namespace coagentics::analysis { using namespace coagentics;
std::string name(Mechanism m){switch(m){case Mechanism::BlindZI:return"blind_zi";case Mechanism::SignalResponsive:return"signal_responsive";case Mechanism::RiskSensitive:return"risk_sensitive";case Mechanism::PeerResponsive:return"peer_responsive";case Mechanism::Adaptive:return"adaptive";}return"unknown";}
static std::unique_ptr<agents::AgentPolicy> make(Mechanism m,std::uint64_t /*seed*/){using market::Side;switch(m){case Mechanism::BlindZI:return std::make_unique<agents::InformationBlindAgent>("A",120,Side::Buy);case Mechanism::SignalResponsive:return std::make_unique<agents::SignalResponsiveAgent>("A",120,Side::Buy,1.0);case Mechanism::RiskSensitive:return std::make_unique<agents::RiskSensitiveAgent>("A",120,Side::Buy,.4);case Mechanism::PeerResponsive:return std::make_unique<agents::PeerResponsiveAgent>("A",120,Side::Buy,.8);case Mechanism::Adaptive:return std::make_unique<agents::AdaptiveAgent>("A",120,Side::Buy,.4);}return{};}
MechanismResult probe_mechanism(Mechanism m,std::uint64_t seed){auto a=make(m,seed);agents::Observation base{0,"ASSET",100,0,0,0,100};auto p0=a->act(base).price;agents::Observation info=base;info.time=1;info.public_signal=10;auto pi=a->act(info).price;auto b=make(m,seed);auto q0=b->act(base).price;agents::Observation peer=base;peer.time=1;peer.last_trade=110;auto pp=b->act(peer).price;double is=pi-p0,ps=pp-q0;bool ok=false;switch(m){case Mechanism::BlindZI:ok=std::abs(is)<1e-9&&std::abs(ps)<1e-9;break;case Mechanism::SignalResponsive:ok=is>5&&std::abs(ps)<1e-9;break;case Mechanism::RiskSensitive:ok=is>0&&is<10&&std::abs(ps)<1e-9;break;case Mechanism::PeerResponsive:ok=std::abs(is)<1e-9&&ps>5;break;case Mechanism::Adaptive:ok=is>5&&ps>0;break;}return{m,is,ps,ok};}
std::vector<MechanismResult> run_benchmark_battery(std::uint64_t seed){std::vector<MechanismResult> r;for(auto m:{Mechanism::BlindZI,Mechanism::SignalResponsive,Mechanism::RiskSensitive,Mechanism::PeerResponsive,Mechanism::Adaptive})r.push_back(probe_mechanism(m,seed));return r;}
}
